using MeiErp.Platform.Reporting;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;
namespace MeiErp.Modules.GatePass;
public static class GatePassReports
{
 public static IServiceCollection AddGatePassReports(this IServiceCollection s){s.AddSingleton<ReportDefinition>(sp=>Make(sp,"outstanding","Outstanding Returnable Goods",false));s.AddSingleton<ReportDefinition>(sp=>Make(sp,"overdue","Overdue Returnable Goods",true));return s;}
 private static ReportDefinition Make(IServiceProvider sp,string key,string name,bool overdue)=>new(){Key="gatepass."+key,Name=name,Description=overdue?"Returnable goods past their expected date.":"Returnable quantities not fully received back.",ModuleKey=GatePassModule.Key,Group="Returns",Permission=GatePassModule.ReportsView,Uses=ReportFilters.None,Run=async(r,ct)=>{using var scope=sp.CreateScope();var today=scope.ServiceProvider.GetRequiredService<MeiErp.Platform.Kernel.IClock>().Today;var rows=await scope.ServiceProvider.GetRequiredService<GatePassDbContext>().Passes.AsNoTracking().Include(x=>x.Items).Where(x=>x.IsReturnable&&x.Status!=PassStatus.Returned&&x.Status!=PassStatus.Cancelled&&(!overdue||x.ExpectedBack<today)).OrderBy(x=>x.ExpectedBack).ToListAsync(ct);var lines=rows.SelectMany(x=>x.Items.Where(i=>i.Outstanding>0).Select(i=>new ReportRow(new Dictionary<string,object?>{{"number",x.Number},{"date",x.Date},{"party",x.PartyName},{"item",i.Description},{"outstanding",i.Outstanding},{"due",x.ExpectedBack},{"status",x.Status}},"/gatepass/passes"))).ToList();return new(){Columns=[new("number","Pass"),new("date","Date",ReportValueKind.Date),new("party","Party"),new("item","Item"),new("outstanding","Outstanding",ReportValueKind.Number),new("due","Expected back",ReportValueKind.Date),new("status","Status",ReportValueKind.Status)],Rows=lines,Totals=[new("outstanding",lines.Sum(x=>Convert.ToDecimal(x["outstanding"]))) ]};}};
}
